import{_ as t,o as s,c as a,y as e}from"./chunks/framework.CNTkXYA8.js";const g=JSON.parse('{"title":"【OI】向量&矩阵乘法","description":"","frontmatter":{"title":"【OI】向量&矩阵乘法","date":"2019-01-20T22:42:00.000Z"},"headers":[],"relativePath":"blog/post-10296381.md","filePath":"source/old_posts/post-10296381.md"}'),o={name:"blog/post-10296381.md"};function c(n,p,i,l,r,d){return s(),a("div",null,[...p[0]||(p[0]=[e('<p>何为向量？</p><p>在初中课本中，我们知道：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>向量是有大小和方向的量。</span></span></code></pre></div><p>这样解释太笼统了，现在我们只讨论平面上的向量。</p><p>那么，我们约定：在平面上的向量，由一个二元组组成：如α(c1,c2)。</p><p>在此平面上建立一个平面直角坐标系，设向量两端点分别为：x1(a1,b1), x2(a2,b2)。</p><p>那么，c1 = a2 - a1, c2 = b2 - b1。</p><p>可以得知，该向量在平面上有无数位置。</p><p>那么，矩阵可以理解为一堆向量的集合。</p><p>比如下面这个矩阵：</p><p><img src="https://img2018.cnblogs.com/blog/1389232/201901/1389232-20190120223310816-1977562308.png" alt=""></p><p>它是一个3 x 4 的矩阵。那么,它拥有4个列向量，3个行向量。</p><p>对于矩阵乘法，我们规定：</p><p>a x b 的矩阵只能乘 b x a 的矩阵。</p><p>类似这样：</p><p><img src="https://img2018.cnblogs.com/blog/1389232/201901/1389232-20190120224136644-1942438090.png" alt=""></p>',16)])])}const b=t(o,[["render",c]]);export{g as __pageData,b as default};
